/**
 *  `GET /api/steam/profile`
 * 
 *  `_cachedAt` 是伺服器記帳（SWR 的抓取時間），不是 profile 的一部分——所以它在
 *  回應型別上，而快取只存 profile 本體（同 watch/now 把 expiresAt 移出 wire type）。
 */
export type SteamProfileResponse = {
	/**  epoch ms */
	_cachedAt: number,
} & SteamProfile;

